{
  "summary": "Build a greenfield Spring Boot URL shortener HTTP service backed by Spring Data JPA and the configured H2 database. Clients can create short links for valid HTTP(S) URLs, follow links through redirects, and retrieve link metadata including click counts.",
  "changeType": "greenfield",
  "functional": [
    "Expose POST /api/links accepting a JSON body with a required string field named url.",
    "Accept only absolute URLs using the http or https scheme with a valid host. Reject missing, blank, malformed, relative, or unsupported-scheme URLs.",
    "For each valid create request, persist a link containing the original URL, a unique short code, and a click count initialized to zero.",
    "Repeated submissions of the same original URL are allowed to create separate links with separate codes; deduplication is not required.",
    "Return the created link from POST /api/links with the generated code, short URL, original URL, and click count.",
    "Expose GET /{code} as the link-following endpoint. For a known code, increment its click count by one and return an HTTP redirect to the original URL.",
    "For an unknown code requested through GET /{code}, return HTTP 404 and do not create or update a link.",
    "Expose GET /api/links/{code} to return the link's code, short URL, original URL, and current click count without incrementing the click count.",
    "For an unknown code requested through GET /api/links/{code}, return HTTP 404 with a clear error response.",
    "Return HTTP 400 for invalid create requests with a JSON error response containing a stable error identifier and a human-readable message.",
    "Persist links using Spring Data JPA and the H2 database configured in the project."
  ],
  "nonFunctional": [
    "Generated codes must be exactly seven characters, use a URL-safe alphabet, and be generated using a cryptographically secure random source so that codes are difficult to guess.",
    "Generated codes must be unique among persisted links; a collision must be detected and retried rather than overwriting an existing link.",
    "The service must return JSON for API success and error responses using the application's normal HTTP content negotiation behavior.",
    "Successful link creation must return HTTP 201.",
    "Successful link lookup must return HTTP 200.",
    "Successful link following must return an HTTP 3xx redirect with a Location header containing the original URL.",
    "Click-count updates must be safe under concurrent follow requests so that each successful follow is counted exactly once.",
    "The implementation must not require persistence across application restarts.",
    "Secrets and credentials must not be hardcoded; none are required for this feature."
  ],
  "outOfScope": [
    "User accounts, authentication, authorization, ownership, or administrative APIs.",
    "Custom aliases, user-selected codes, bulk link creation, or link deletion.",
    "Expiration dates, click-history timestamps, analytics beyond the aggregate click count, and geographic or referrer tracking.",
    "Rate limiting, abuse detection, URL content scanning, malware detection, or destination availability checks.",
    "Following redirects from the destination URL or proxying destination content.",
    "Guaranteeing that different submissions of the same URL reuse a code.",
    "A production-grade database migration strategy or persistence guarantees across restarts."
  ],
  "openQuestions": [
    {
      "question": "What exact public base URL should be used when constructing the shortUrl returned by the API?",
      "assumption": "Use a configurable application property named shortener.base-url when supplied; otherwise derive the base from the incoming request scheme, host, and port. The generated short URL is the base URL followed by /{code}.",
      "answer": ""
    },
    {
      "question": "Should URL validation permit URL user-info, fragments, query strings, internationalized domains, or nonstandard ports?",
      "assumption": "Permit valid absolute HTTP(S) URLs including query strings, fragments, and ports. Require a nonempty host and reject malformed URI syntax; no additional destination-content validation is performed.",
      "answer": ""
    },
    {
      "question": "What JSON property name and error schema should clients rely on for validation and not-found errors?",
      "assumption": "Use an error object with stable fields error and message. Use error values invalid_url for rejected URLs or malformed create payloads and not_found for unknown codes.",
      "answer": ""
    },
    {
      "question": "Should the short-code alphabet exclude visually ambiguous characters or reserve codes that conflict with API paths?",
      "assumption": "Use a URL-safe alphanumeric alphabet, exclude characters that require URL encoding, and ensure generated codes cannot equal reserved top-level route names such as api. A seven-character code is the fixed interpretation of 'about 7 characters'.",
      "answer": ""
    },
    {
      "question": "Should a follow request increment the click count for every successful redirect response, including repeated requests and requests from automated clients?",
      "assumption": "Yes. Every successful GET /{code} that resolves a known link increments the aggregate count exactly once, regardless of client type; metadata requests do not increment it.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid absolute HTTP URL, POST /api/links with Content-Type application/json and body {\"url\":\"https://example.com/path\"} returns HTTP 201 and a JSON body containing the original URL, a seven-character code, a shortUrl ending in /{code}, and clickCount equal to 0."
    },
    {
      "id": "AC2",
      "criterion": "Given two successful POST /api/links requests containing the same valid URL, both requests return HTTP 201 and their returned codes are different."
    },
    {
      "id": "AC3",
      "criterion": "Given a missing, blank, malformed, relative, or non-http(s) url value, POST /api/links returns HTTP 400 with a JSON body containing error equal to invalid_url and a non-empty human-readable message."
    },
    {
      "id": "AC4",
      "criterion": "Given a link created with code C and original URL U, GET /api/links/C returns HTTP 200 with JSON fields code equal to C, original URL equal to U, shortUrl ending in /C, and clickCount equal to the current count."
    },
    {
      "id": "AC5",
      "criterion": "Given a link with code C and clickCount N, GET /C returns an HTTP 3xx response with a Location header equal to the original URL and a subsequent GET /api/links/C reports clickCount N+1."
    },
    {
      "id": "AC6",
      "criterion": "Given a link with code C and clickCount N, calling GET /api/links/C does not change the count; a subsequent GET /api/links/C still reports clickCount N."
    },
    {
      "id": "AC7",
      "criterion": "Given a code that has never been created, GET /{unknownCode} returns HTTP 404 with error equal to not_found, and GET /api/links/{unknownCode} returns HTTP 404 with error equal to not_found."
    },
    {
      "id": "AC8",
      "criterion": "Given a known code C, sending multiple follow requests to GET /C results in the link details reporting a clickCount increased by exactly the number of successful follow requests."
    },
    {
      "id": "AC9",
      "criterion": "For every successfully created link, the returned code consists of exactly seven URL-safe characters and repeated creation requests do not cause an existing code's details or destination to be overwritten."
    },
    {
      "id": "AC10",
      "criterion": "A link created through POST /api/links can be retrieved through GET /api/links/{code} and followed through GET /{code} while the service is running, demonstrating that the link is persisted and available through both HTTP interfaces."
    }
  ],
  "decisions": [
    {
      "title": "Use separate API and redirect routes",
      "rationale": "The requirement needs both link-management operations and a root-level redirect while avoiding ambiguity between API resources and generated codes.",
      "alternatives": [
        "Use /links and /links/{code} for all operations",
        "Use /api/shorten and /r/{code} for the redirect"
      ]
    },
    {
      "title": "Return HTTP 201 for link creation",
      "rationale": "Creation of a new persisted resource is conventionally represented by HTTP 201 and makes the API behavior explicit.",
      "alternatives": [
        "Return HTTP 200 for all successful operations",
        "Return HTTP 202 for asynchronous creation"
      ]
    },
    {
      "title": "Use a fixed seven-character cryptographically random code",
      "rationale": "This provides a concrete, testable interpretation of 'about 7 characters', avoids predictable sequential identifiers, and supports compact URLs.",
      "alternatives": [
        "Use sequential numeric identifiers",
        "Use UUIDs or longer opaque identifiers",
        "Use a hash of the original URL"
      ]
    },
    {
      "title": "Count only successful known-code follows",
      "rationale": "A click represents a resolved redirect; unknown codes cannot be attributed to a link and must not affect any count.",
      "alternatives": [
        "Count every request including 404 responses",
        "Count metadata lookups as clicks"
      ]
    },
    {
      "title": "Do not deduplicate identical URLs",
      "rationale": "The requirement explicitly permits a new code for each submission, so treating each valid submission as a new link avoids imposing deduplication behavior.",
      "alternatives": [
        "Return the existing link for an identical URL",
        "Make deduplication configurable"
      ]
    },
    {
      "title": "Derive the short URL from configuration or the request origin",
      "rationale": "The requirement requires a short URL but does not specify a deployment hostname; this supports both configured deployments and local HTTP testing.",
      "alternatives": [
        "Return only a relative path",
        "Hardcode localhost as the short URL host",
        "Require shortener.base-url with no fallback"
      ]
    },
    {
      "title": "Use an aggregate click count without click-event history",
      "rationale": "The requirement asks for how many times a link was followed and does not require audit records or analytics detail.",
      "alternatives": [
        "Persist one click record per follow",
        "Store daily or timestamped click aggregates"
      ]
    }
  ]
}

