"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;

import org.springframework.stereotype.Component;

@Component
public class UrlValidator {

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("URL must not be missing or blank");
        }

        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute()
                    || scheme == null
                    || !(scheme.toLowerCase(Locale.ROOT).equals("http")
                    || scheme.toLowerCase(Locale.ROOT).equals("https"))
                    || uri.getHost() == null
                    || uri.getHost().isBlank()) {
                throw new InvalidUrlException("URL must be an absolute HTTP or HTTPS URL with a valid host");
            }
        } catch (URISyntaxException ex) {
            throw new InvalidUrlException("URL is malformed");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/CodeGenerator.java","content":"package com.example.shortener;

import java.security.SecureRandom;

import org.springframework.stereotype.Component;

@Component
public class CodeGenerator {

    private static final String ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private static final int CODE_LENGTH = 7;
    private final SecureRandom random = new SecureRandom();

    public String generate() {
        StringBuilder code = new StringBuilder(CODE_LENGTH);
        for (int i = 0; i < CODE_LENGTH; i++) {
            code.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        }
        return code.toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/ShortUrlBuilder.java","content":"package com.example.shortener;

import jakarta.servlet.http.HttpServletRequest;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class ShortUrlBuilder {

    private final String configuredBaseUrl;

    public ShortUrlBuilder(@Value("${shortener.base-url:}") String configuredBaseUrl) {
        this.configuredBaseUrl = configuredBaseUrl == null ? "" : configuredBaseUrl.trim();
    }

    public String build(String code, HttpServletRequest request) {
        String base = configuredBaseUrl;
        if (base.isEmpty()) {
            base = request.getScheme() + "://" + request.getServerName();
            int port = request.getServerPort();
            boolean defaultPort = ("http".equalsIgnoreCase(request.getScheme()) && port == 80)
                    || ("https".equalsIgnoreCase(request.getScheme()) && port == 443);
            if (!defaultPort && port > 0) {
                base += ":" + port;
            }
        }
        while (base.endsWith("/")) {
            base = base.substring(0, base.length() - 1);
        }
        return base + "/" + code;
    }
}
