"},{"path":"src/main/java/com/example/shortener/LinkService.java","content":"package com.example.shortener;

import jakarta.servlet.http.HttpServletRequest;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class LinkService {

    private static final int MAX_CREATE_ATTEMPTS = 10;

    private final LinkRepository repository;
    private final UrlValidator urlValidator;
    private final CodeGenerator codeGenerator;
    private final ShortUrlBuilder shortUrlBuilder;
    private final TransactionTemplate transactionTemplate;

    public LinkService(LinkRepository repository,
                       UrlValidator urlValidator,
                       CodeGenerator codeGenerator,
                       ShortUrlBuilder shortUrlBuilder,
                       PlatformTransactionManager transactionManager) {
        this.repository = repository;
        this.urlValidator = urlValidator;
        this.codeGenerator = codeGenerator;
        this.shortUrlBuilder = shortUrlBuilder;
        this.transactionTemplate = new TransactionTemplate(transactionManager);
    }

    public LinkResponse create(String originalUrl, HttpServletRequest request) {
        urlValidator.validate(originalUrl);
        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
            String code = codeGenerator.generate();
            try {
                Link link = transactionTemplate.execute(status -> repository.saveAndFlush(new Link(code, originalUrl)));
                return toResponse(link, request);
            } catch (DataIntegrityViolationException ex) {
                // A unique-code collision is safe to retry in a new transaction.
            }
        }
        throw new CodeGenerationException();
    }

    @Transactional(readOnly = true)
    public LinkResponse find(String code, HttpServletRequest request) {
        Link link = repository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
        return toResponse(link, request);
    }

    @Transactional
    public String follow(String code) {
        Link link = repository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
        if (repository.incrementClickCount(code) != 1) {
            throw new LinkNotFoundException(code);
        }
        return link.getOriginalUrl();
    }

    private LinkResponse toResponse(Link link, HttpServletRequest request) {
        return new LinkResponse(link.getCode(), shortUrlBuilder.build(link.getCode(), request),
                link.getOriginalUrl(), link.getClickCount());
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkController.java","content":"package com.example.shortener;

import java.net.URI;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping
public class LinkController {

    private final LinkService linkService;

    public LinkController(LinkService linkService) {
        this.linkService = linkService;
    }

    @PostMapping("/api/links")
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest request,
                                                HttpServletRequest httpRequest) {
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(linkService.create(request.url(), httpRequest));
    }

    @GetMapping("/api/links/{code}")
    public LinkResponse details(@PathVariable String code, HttpServletRequest request) {
        return linkService.find(code, request);
    }

    @GetMapping("/{code}")
    public ResponseEntity<Void> follow(@PathVariable String code) {
        if ("api".equalsIgnoreCase(code)) {
            throw new LinkNotFoundException(code);
        }
        String destination = linkService.follow(code);
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(URI.create(destination));
        return ResponseEntity.status(HttpStatus.FOUND).headers(headers).build();
    }
}
"},{"path":"src/main/java/com/example/shortener/ApiExceptionHandler.java","content":"package com.example.shortener;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;

@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler({InvalidUrlException.class, MethodArgumentNotValidException.class,
            HttpMessageNotReadableException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ProblemDetail invalidUrl(Exception exception) {
        String message = exception instanceof InvalidUrlException
                ? exception.getMessage() : "Request must contain a valid HTTP or HTTPS URL";
        return problem(HttpStatus.BAD_REQUEST, "invalid_url", message);
    }

    @ExceptionHandler(LinkNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public ProblemDetail notFound(LinkNotFoundException exception) {
        return problem(HttpStatus.NOT_FOUND, "not_found", exception.getMessage());
    }

    @ExceptionHandler(CodeGenerationException.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public ProblemDetail codeGeneration(CodeGenerationException exception) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "internal_error", exception.getMessage());
    }

    private ProblemDetail problem(HttpStatus status, String error, String message) {
        ProblemDetail detail = ProblemDetail.forStatusAndDetail(status, message);
        detail.setProperty("error", error);
        detail.setProperty("message", message);
        return detail;
    }
}
