    void generatesSevenUrlSafeCharacters() {
        CodeGenerator generator = new CodeGenerator();

        String code = generator.generate();

        assertThat(code).hasSize(7).matches("[A-Za-z0-9]{7}");
    }

    @Test
    void derivesShortUrlWithoutDefaultPort() {
        ShortUrlBuilder builder = new ShortUrlBuilder("");
        HttpServletRequest request = mock(HttpServletRequest.class);
        when(request.getScheme()).thenReturn("https");
        when(request.getServerName()).thenReturn("short.example");
        when(request.getServerPort()).thenReturn(443);

        assertThat(builder.build("Ab3xYz9", request))
                .isEqualTo("https://short.example/Ab3xYz9");
    }

    @Test
    void usesConfiguredBaseAndRemovesTrailingSlashes() {
        ShortUrlBuilder builder = new ShortUrlBuilder("https://short.example///");

        assertThat(builder.build("Ab3xYz9", mock(HttpServletRequest.class)))
                .isEqualTo("https://short.example/Ab3xYz9");
