"},{"path":"src/test/java/com/example/shortener/UrlValidatorTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class UrlValidatorTest {

    private final UrlValidator validator = new UrlValidator();

    @Test
    void acceptsAbsoluteHttpAndHttpsUrls() {
        validator.validate("https://example.com/path?q=1#fragment");
        validator.validate("HTTP://example.com:8080/path");
    }

    @ParameterizedTest
    @MethodSource("invalidUrls")
    void rejectsMissingBlankMalformedRelativeAndUnsupportedUrls(String value) {
        Throwable thrown = org.assertj.core.api.Assertions.catchThrowable(() -> validator.validate(value));

        assertThat(thrown).isInstanceOf(InvalidUrlException.class);
        assertThat(thrown.getMessage()).isNotBlank();
    }

    private static Stream<Arguments> invalidUrls() {
        return Stream.of(
                Arguments.of((String) null),
                Arguments.of(""),
                Arguments.of("   "),
                Arguments.of("not a url"),
                Arguments.of("/relative/path"),
                Arguments.of("ftp://example.com/file"),
                Arguments.of("https:///missing-host"),
                Arguments.of("https://"));
    }
}
