    }

    @Test
    void reportsCodeGenerationFailureAfterBoundedCollisions() {
        LinkRepository repository = mock(LinkRepository.class);
        UrlValidator validator = mock(UrlValidator.class);
        CodeGenerator generator = mock(CodeGenerator.class);
        ShortUrlBuilder builder = mock(ShortUrlBuilder.class);
        PlatformTransactionManager transactionManager = mock(PlatformTransactionManager.class);
        TransactionStatus status = mock(TransactionStatus.class);
        HttpServletRequest request = mock(HttpServletRequest.class);

        when(transactionManager.getTransaction(any())).thenReturn(status);
        when(generator.generate()).thenReturn("AAAAAAA");
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate"));
        doNothing().when(validator).validate("https://example.com");

        LinkService service = new LinkService(repository, validator, generator, builder, transactionManager);

        assertThatThrownBy(() -> service.create("https://example.com", request))
                .isInstanceOf(CodeGenerationException.class);
    }

    @Test
    void followLoadsDestinationAndPerformsExactlyOneIncrement() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortUrlBuilder builder = mock(ShortUrlBuilder.class);
        UrlValidator validator = mock(UrlValidator.class);
        CodeGenerator generator = mock(CodeGenerator.class);
        PlatformTransactionManager transactionManager = mock(PlatformTransactionManager.class);
        Link link = new Link("AAAAAAA", "https://example.com/destination");

        when(repository.findByCode("AAAAAAA")).thenReturn(java.util.Optional.of(link));
        when(repository.incrementClickCount("AAAAAAA")).thenReturn(1);

        LinkService service = new LinkService(repository, validator, generator, builder, transactionManager);

        assertThat(service.follow("AAAAAAA")).isEqualTo("https://example.com/destination");
        verify(repository).incrementClickCount("AAAAAAA");
    }
